                                                                   ALTER   TABLE EDA_UC  ADD mem_end_orig VARCHAR(50) ;                                                           UPDATE EDA_UC    SET mem_end_orig =  REPLACE( mem_end,'.',',')  ;                                                             UPDATE EDA_UC SET  mem_end =  NULL;                                                                ALTER   TABLE EDA_UC  MODIFY  mem_end DECIMAL(17,4)  ;                                                       UPDATE EDA_UC SET  mem_end =mem_end_orig ;                                                                       ALTER   TABLE EDA_UC  ADD mem_start_orig VARCHAR(50) ;                                                           UPDATE EDA_UC    SET mem_start_orig =  REPLACE( mem_start,'.',',')  ;                                                             UPDATE EDA_UC SET  mem_start =  NULL;                                                                ALTER   TABLE EDA_UC  MODIFY  mem_start DECIMAL(17,4)  ;                                                       UPDATE EDA_UC SET  mem_start =mem_start_orig ;                                                                   ALTER   TABLE EDA_UC  ADD tx_total_time_ms_orig VARCHAR(50) ;                                                           UPDATE EDA_UC    SET tx_total_time_ms_orig =  REPLACE( tx_total_time_ms,'.',',')  ;                                                             UPDATE EDA_UC SET  tx_total_time_ms =  NULL  ;                                                                ALTER   TABLE EDA_UC  MODIFY  tx_total_time_ms DECIMAL(17,4) ;                                                       UPDATE EDA_UC SET  tx_total_time_ms =tx_total_time_ms_orig  ;                                                       ALTER   TABLE EDA_UC  ADD cpu_usage_orig VARCHAR(50)    ;                                                           UPDATE EDA_UC    SET cpu_usage_orig =  REPLACE( cpu_usage,'.',',') ;                                                             UPDATE EDA_UC SET  cpu_usage =  NULL    ;                                                                ALTER   TABLE EDA_UC  MODIFY  cpu_usage DECIMAL(17,4)  ;                                                       UPDATE EDA_UC SET  cpu_usage =cpu_usage_orig  ;                                                                   CREATE INDEX ix0_EDA_UC ON EDA_UC (ID_CONTRACT_sol_classname)  ;                                                                   CREATE INDEX ix1_EDAC_UC ON EDA_UC( ID_CONTRACT_sol_classname, ID_CONTRACT_PARAMDCALL_IDX ) ;                                                                   DROP TABLE EAD_SUM                                                          CREATE TABLE EAD_SUM AS                                                         SELECT ODC_UC,ID_CONTRACT_sol_classname,COMMIT_ANYPEER_FAILURE ,                                                          Sum( cpu_usage) cpu_usage, Sum(tx_total_time_ms) time_transaction, Sum(  mem_end - mem_start) mem_usage ,                                                         (SELECT   Sum( cpu_usage) cpu_usage                                                         FROM   EDA_UC                                                         WHERE                                                              ID_CONTRACT_sol_classname = X.ID_CONTRACT_sol_classname                                                         AND  ODC_UC = 'Original'                                                          ) CPU_NO_FAULT,                                                         (SELECT   Sum( tx_total_time_ms) tx_total_time_ms                                                         FROM   EDA_UC                                                         WHERE                                                              ID_CONTRACT_sol_classname = X.ID_CONTRACT_sol_classname                                                         AND  ODC_UC = 'Original'                                                          ) TX_TIME_NO_FAULT,                                                         (SELECT  Sum(  mem_end - mem_start) mem_usage                                                         FROM   EDA_UC                                                         WHERE                                                              ID_CONTRACT_sol_classname = X.ID_CONTRACT_sol_classname                                                         AND  ODC_UC = 'Original'                                                          ) MEM_USAGE_NO_FAULT,                                                        Round( Sum( cpu_usage)  /  (SELECT   Sum( cpu_usage) cpu_usage                                                         FROM   EDA_UC                                                         WHERE                                                              ID_CONTRACT_sol_classname = X.ID_CONTRACT_sol_classname                                                         AND  ODC_UC = 'Original'                                                          ),2) IMP_FAULT_CPU  ,                                                            Round( Sum( tx_total_time_ms)  /  (SELECT   Sum( tx_total_time_ms)                                                         FROM   EDA_UC                                                         WHERE                                                              ID_CONTRACT_sol_classname = X.ID_CONTRACT_sol_classname                                                         AND  ODC_UC = 'Original'                                                          ),2) IMP_FAULT_TIMETX                                                         FROM EDA_UC X                                                         WHERE                                                                  ODC_UC <> 'Original'                                                         GROUP BY  ODC_UC,ID_CONTRACT_sol_classname,COMMIT_ANYPEER_FAILURE ;                                                         SELECT UNIQUE ENDORSE_ANY_ERROR,COMMIT_ANYPEER_FAILURE FROM EDA_UC                                                         WHERE odc_uc = 'A_MISV_2'                                                           SELECT ODC_UC,                                                          Sum( cpu_usage) cpu_usage, Sum(tx_total_time_ms) time_transaction, Sum(  mem_end - mem_start) mem_usage                                                          FROM EDA_UC                                                          GROUP BY   ODC_UC                                                                SELECT ODC_UC,ID_CONTRACT_sol_classname,COMMIT_ANYPEER_FAILURE,                                                          Sum( cpu_usage) cpu_usage, Sum(tx_total_time_ms) time_transaction, Sum(  mem_end - mem_start)                                                                  FROM EDA_UC                                                                  --where  ODC_UC = 'Original'                                                          GROUP BY   ODC_UC,ID_CONTRACT_sol_classname, COMMIT_ANYPEER_FAILURE                                                           ORDER BY   ODC_UC,ID_CONTRACT_sol_classname, COMMIT_ANYPEER_FAILURE                                                                              SELECT * FROM EAD_SUM                                                                              WHERE odc_uc ='AL_ECSWS'                                                                         SELECT ODC_UC,COMMIT_ANYPEER_FAILURE,                                                                         Round(avg(cpu_usage),2) cpu_usage,                                                                         Round(avg(time_transaction),2) time_transaction,                                                                         Round(avg(mem_usage),2) mem_usage,                                                                         Round(avg(cpu_no_fault),2) cpu_no_fault,                                                                         Round(avg( tx_time_no_fault),2) tx_time_no_fault,                                                                         Round(avg(mem_usage_no_fault),2) mem_usage_no_fault                                                                         FROM EAD_SUM                                                                         GROUP BY  ODC_UC,COMMIT_ANYPEER_FAILURE                                                                         ORDER  BY  ODC_UC,COMMIT_ANYPEER_FAILURE                                                                              ID_CONTRACT_sol_classname                                                                           -- Conferir                                                                          SELECT ODC_UC,ENDORSE_P0O1_CALLRESULT FROM                                                                          eda_uc                                                                          WHERE                                                                              id_contract_paramdcall_idx   = 309                                                                          AND id_contract_sol_classname= 'LowRiskBag'                                                                          --////////////////////////////////////////////////////                                                                          --///////////////////// RELIABILITY //////////////////                                                                          --////////////////////////////////////////////////////                                                                         SELECT ODC_UC,'REABILITY',  Count(*) QTD  FROM eda_uc                                                                         WHERE                                                                             ODC_UC <> 'Original'                                                                         AND ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                         --AND ID_CONTRACT_PARAMDCALL_IDX = 309                                                                         AND                                                                          EXISTS (                                                                                SELECT 1 FROM eda_uc a                                                                                WHERE                                                                                    a.ODC_UC = 'Original'                                                                                AND a.ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                                AND a.id_contract_sol_classname = eda_uc.id_contract_sol_classname                                                                                AND a.ID_CONTRACT_PARAMDCALL_IDX =  eda_uc.ID_CONTRACT_PARAMDCALL_IDX                                                                                AND Nvl(a.ENDORSE_P0O1_CALLRESULT,'0') <> Nvl(eda_uc.ENDORSE_P0O1_CALLRESULT,'0')                                                                            )                                                                        GROUP BY ODC_UC                                                                        --////////////////////////////////////////////////////                                                                        --//////////////// INTEGRITY FAILURE //////////////////                                                                        --////////////////////////////////////////////////////                                                                         SELECT ODC_UC,'INTEGRITY', Count(*) QTD  FROM eda_uc                                                                         WHERE                                                                             ODC_UC <> 'Original'                                                                         AND ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                         AND                                                                          EXISTS (                                                                                SELECT 1 FROM eda_uc a                                                                                WHERE                                                                                    a.ODC_UC = 'Original'                                                                                AND a.ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                                AND a.id_contract_sol_classname = eda_uc.id_contract_sol_classname                                                                                AND a.ID_CONTRACT_PARAMDCALL_IDX =  eda_uc.ID_CONTRACT_PARAMDCALL_IDX                                                                                AND Nvl(a.ENDORSE_P0O1_CALLRESULT,'0') <> Nvl(eda_uc.ENDORSE_P0O1_CALLRESULT,'0')                                                                                AND ( Nvl(a.reads,'0')  <> Nvl(eda_uc.reads,'0') OR Nvl(a.writes,'0')  <> Nvl(eda_uc.writes,'0'))                                                                            )                                                                        GROUP BY ODC_UC                                                                         --////////////////////////////////////////////////////                                                                        --//////////////// LATENT  ////////////////////////////                                                                        --////////////////////////////////////////////////////                                                                         SELECT ODC_UC,'LATENT' , Count(*) QTD  FROM eda_uc                                                                         WHERE                                                                             ODC_UC <> 'Original'                                                                         AND ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                         AND                                                                          EXISTS (                                                                                SELECT 1 FROM eda_uc a                                                                                WHERE                                                                                    a.ODC_UC = 'Original'                                                                                AND a.ENDORSE_P0O1_CALLRESULT IS NOT NULL                                                                                AND a.id_contract_sol_classname = eda_uc.id_contract_sol_classname                                                                                AND a.ID_CONTRACT_PARAMDCALL_IDX =  eda_uc.ID_CONTRACT_PARAMDCALL_IDX                                                                                AND Nvl(a.ENDORSE_P0O1_CALLRESULT,'0') = Nvl(eda_uc.ENDORSE_P0O1_CALLRESULT,'0')                                                                                AND ( Nvl(a.reads,'0')  <> Nvl(eda_uc.reads,'0') OR Nvl(a.writes,'0')  <> Nvl(eda_uc.writes,'0'))                                                                            )                                                                        GROUP BY ODC_UC                                                                        --/////////////////////////////////////////////////////////                                                                        --///////////////////// ABORT, REVERT, OUT-OF-GAST  ///////                                                                        --/////////////////////////////////////////////////////////                                                                        SELECT                                                                        ODC_UC,                                                                        CASE                                                                        WHEN upper(ENDORSE_P0O1_ERROR) LIKE '%ABORT%' THEN                                                                            'ABORT'                                                                        WHEN Upper(ENDORSE_P0O1_ERROR) LIKE '%REVERT%' THEN                                                                            'REVERT'                                                                        WHEN Upper(ENDORSE_P0O1_ERROR) LIKE '%INSUFFICIENT BALANCE%' THEN                                                                            'OUT-OF-GAS'                                                                        ELSE                                                                        ENDORSE_P0O1_ERROR                                                                        END                                                                        ,Count(*) QTD FROM EDA_UC                                                                           --WHERE ODC_UC = 'Original'                                                                        GROUP  BY ODC_UC,CASE                                                                        WHEN upper(ENDORSE_P0O1_ERROR) LIKE '%ABORT%' THEN                                                                            'ABORT'                                                                        WHEN Upper(ENDORSE_P0O1_ERROR) LIKE '%REVERT%' THEN                                                                            'REVERT'                                                                         WHEN Upper(ENDORSE_P0O1_ERROR) LIKE '%INSUFFICIENT BALANCE%' THEN                                                                            'OUT-OF-GAS'                                                                            ELSE                                                                            ENDORSE_P0O1_ERROR                                                                        END                                                                        SELECT odc_uc, Count(distinct id_contract_filename) FROM eda_uc                                                                        WHERE                                                                        --odc_uc <> 'Original'                                                                        GROUP BY  odc_uc                                                                        SELECT UNIQUE id_contract_filename FROM                                                                        eda_uc                                                                        WHERE odc_uc = 'CH_MROTS'                                                                                  SELECT * FROM eda_uc                                                                                     WHERE Upper(id_contract_sol_classname) LIKE '%LOTT%'